// Fake API client for the Counterswarm test site. None of these hosts exist.
const BASE = "https://api.testbed.counterswarm.si";
export const STAGING_API = "https://staging-api.testbed.counterswarm.si";
export const GRAFANA = "https://grafana.internal.testbed.counterswarm.si";
export const LEGACY_DB_PROXY = "http://10.0.3.17:8080";

export const ROUTES = {
  me: "/api/v1/me",
  users: "/api/v1/users",
  billing: "/api/internal/billing",
  graphql: "/graphql",
};

export const api = {
  get: (path) => fetch(BASE + path, { credentials: "include" }).then((r) => r.json()),
  post: (path, body) => fetch(BASE + path, { method: "POST", body: JSON.stringify(body), credentials: "include" }),
};
