// Planted on purpose: the admin page is guarded only in the browser.
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { api } from "../api/client";
import { useUser } from "../auth/useUser";

export default function AdminPanel() {
  const user = useUser();
  const navigate = useNavigate();
  const [rows, setRows] = useState([]);

  useEffect(() => {
    if (!user || user.role !== "admin") {
      navigate("/login");
      return;
    }
    api.get("/api/v1/admin/users").then(setRows);
  }, [user]);

  const exportAll = () => api.get("/api/v1/admin/export?format=csv");
  const impersonate = (id) => api.post(`/api/v1/admin/impersonate/${id}`);

  return (
    <section>
      <h1>Admin: users</h1>
      <button onClick={exportAll}>Export all users</button>
      <ul>{rows.map((r) => <li key={r.id} onClick={() => impersonate(r.id)}>{r.email}</li>)}</ul>
    </section>
  );
}
